-- Rollback-only synthetic customers. No Horizonte state is entered or changed.
begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('4d8d0000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,aud,role,email,email_confirmed_at,encrypted_password) values(pg_temp.id(1),'authenticated','authenticated','delegator-sql@example.invalid',clock_timestamp(),'synthetic');
insert into persons(id,auth_user_id,display_name) values(pg_temp.id(2),pg_temp.id(1),'Fictional Delegator');
insert into accounts(id,code,name,tenant_kind) values(pg_temp.id(3),'DELEGATION-SQL-C','Fictional Customer','customer'),(pg_temp.id(13),'DELEGATION-SQL-S','Fictional Sandbox','sandbox');
insert into schools(id,account_id,code,name) values(pg_temp.id(4),pg_temp.id(3),'S','Fictional School'),(pg_temp.id(14),pg_temp.id(13),'S','Fictional Sandbox School');
insert into school_locations(id,account_id,school_id,code,name) values(pg_temp.id(5),pg_temp.id(3),pg_temp.id(4),'L','Fictional Location'),(pg_temp.id(15),pg_temp.id(13),pg_temp.id(14),'L','Fictional Sandbox Location');
insert into cafeterias(id,account_id,school_id,school_location_id,code,name) values(pg_temp.id(6),pg_temp.id(3),pg_temp.id(4),pg_temp.id(5),'C','Fictional Cafe'),(pg_temp.id(16),pg_temp.id(13),pg_temp.id(14),pg_temp.id(15),'C','Fictional Sandbox Cafe');
insert into account_memberships(account_id,person_id,role_code) values(pg_temp.id(3),pg_temp.id(2),'account_admin');
insert into auth.sessions(id,user_id,created_at,updated_at) values(pg_temp.id(7),pg_temp.id(1),clock_timestamp(),clock_timestamp());
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(1),'role','authenticated','session_id',pg_temp.id(7))::text,true);
set local role authenticated;
select pikas_session_start();
select is(get_cafeteria_admin_context()->'cafeterias','[]'::jsonb,'account admin has no implicit cafeteria authority');
select lives_ok($$select cafeteria_delegation_command(pg_temp.id(4),pg_temp.id(6),pg_temp.id(8),'cafeteria_admin_self',jsonb_build_object('cafeteria_id',pg_temp.id(6)))$$,'explicit self assignment');
select lives_ok($$select cafeteria_delegation_command(pg_temp.id(4),pg_temp.id(6),pg_temp.id(8),'cafeteria_admin_self',jsonb_build_object('cafeteria_id',pg_temp.id(6)))$$,'exact retry');
select throws_ok($$select cafeteria_delegation_command(pg_temp.id(4),pg_temp.id(6),pg_temp.id(8),'cafeteria_admin_prepare',jsonb_build_object('cafeteria_id',pg_temp.id(6),'email','fictional@example.invalid'))$$,'42501','delegation_request_mismatch','mismatched replay denied');
select throws_ok($$select cafeteria_delegation_command(pg_temp.id(4),pg_temp.id(6),pg_temp.id(9),'cafeteria_admin_self',jsonb_build_object('cafeteria_id',pg_temp.id(6),'role','pos_cashier'))$$,'22023','invalid_delegation_payload','client role denied');
reset role;
select is((select count(*)::int from cafeteria_memberships where person_id=pg_temp.id(2)),1,'one explicit membership');
select is((select count(*)::int from cafeteria_memberships where person_id=pg_temp.id(2) and role_code in ('pos_cashier','pos_supervisor')),0,'admin is not cashier');
select is((select count(*)::int from audit_events where request_id=pg_temp.id(8) and authenticated_user_id=pg_temp.id(1) and actor_person_id=pg_temp.id(2) and cafeteria_id=pg_temp.id(6)),1,'audit binds real actor and exact cafeteria once');
select is((select count(*)::int from pikas_private.school_admin_requests where request_id=pg_temp.id(8)),1,'one durable result');
select ok(not has_function_privilege('anon','public.cafeteria_delegation_command(uuid,uuid,uuid,text,jsonb)','execute'),'anon denied');
select ok(not has_function_privilege('service_role','public.cafeteria_delegation_command(uuid,uuid,uuid,text,jsonb)','execute'),'provider cannot delegate');
select ok(not has_schema_privilege('service_role','pikas_private','usage'),'private schema remains closed');
-- Synthetic active POV attempt: even an otherwise authorized real account admin cannot delegate.
insert into persons(id,display_name) values(pg_temp.id(17),'Fictional Authless Persona');
insert into cafeteria_memberships(id,account_id,school_id,cafeteria_id,person_id,role_code) values(pg_temp.id(18),pg_temp.id(13),pg_temp.id(14),pg_temp.id(16),pg_temp.id(17),'cafeteria_admin');
insert into pikas_private.sandbox_pov_personas(id,account_id,school_id,cafeteria_id,pov_code,person_id,cafeteria_membership_id) values(pg_temp.id(19),pg_temp.id(13),pg_temp.id(14),pg_temp.id(16),'cafeteria_admin',pg_temp.id(17),pg_temp.id(18));
insert into pikas_private.sandbox_pov_sessions(request_id,initiator_person_id,initiator_auth_user_id,account_id,school_id,cafeteria_id,pov_code,persona_id,persona_person_id,persona_membership_id,expires_at) values(pg_temp.id(20),pg_temp.id(2),pg_temp.id(1),pg_temp.id(13),pg_temp.id(14),pg_temp.id(16),'cafeteria_admin',pg_temp.id(19),pg_temp.id(17),pg_temp.id(18),clock_timestamp()+interval '1 hour');
set local role authenticated;
select throws_ok($$select cafeteria_delegation_command(pg_temp.id(4),pg_temp.id(6),pg_temp.id(21),'cafeteria_admin_self',jsonb_build_object('cafeteria_id',pg_temp.id(6)))$$,'42501','customer_account_admin_required','active sandbox POV cannot delegate');
select * from finish();
rollback;
